const (
	rootCmdDesc = "cnspec is a cloud-native security testing tool for your entire infrastructure\n"
)

const cnspecLogo = "  ___ _ __  ___ _ __   ___  ___ \n" +
	" / __| '_ \\/ __| '_ \\ / _ \\/ __|\n" +
	"| (__| | | \\__ \\ |_) |  __/ (__ \n" +
	" \\___|_| |_|___/ .__/ \\___|\\___|\n" +
	"   mondoo™     |_|              "

const (
	errorMessageServiceAccount = "invalid service account configuration"
)

func init() {
	theme.DefaultTheme.Landing = landing()
}

func landing() string {
	// windows
	if runtime.GOOS == "windows" {
		return termenv.String(cnspecLogo + "\n").Foreground(colors.DefaultColorTheme.Primary).String()
	}
	// unix
	return termenv.String(cnspecLogo).Foreground(colors.DefaultColorTheme.Primary).String()
}

// rootCmd represents the base command when called without any subcommands
var rootCmd = &cobra.Command{
	Use:   "cnspec",
	Short: "cnspec CLI",
	// NOTE: if we use theme.DefaultTheme.Landing go compiler uses the value before init updated it
	Long: landing() + "\n\n" + rootCmdDesc,
	PersistentPreRun: func(cmd *cobra.Command, args []string) {
		initLogger(cmd)
	},
}

func BuildRootCmd() (*cobra.Command, error) {
	err := providers.AttachCLIs(
		rootCmd,
		&providers.Command{
			Command: shellCmd,
			Run:     shellRun,
			Action:  "Interactive shell with ",
		},
		&providers.Command{
			Command: cnquery_app.RunCmd,
			Run:     cnquery_app.RunCmdRun,
			Action:  "Run a query with ",
		},
		&providers.Command{
			Command: scanCmd,
			Run:     scanCmdRun,
			Action:  "Scan ",
		},
		&providers.Command{
			Command:             vulnCmd,
			Run:                 vulnCmdRun,
			Action:              "Check for vulnerabilities ",
			SupportedConnectors: []string{"docker", "container", "filesystem", "local", "ssh", "vagrant", "winrm", "vsphere", "sbom"},
		},
		&providers.Command{
			Command:             sbomCmd,
			Run:                 sbomCmdRun,
			Action:              "Collect a software bill of materials (SBOM) for ",
			SupportedConnectors: []string{"docker", "container", "filesystem", "local", "ssh", "vagrant", "winrm", "sbom"},
		},
	)
	return rootCmd, err
}

// Execute adds all child commands to the root command and sets flags appropriately.
// This is called by main.main(). It only needs to happen once to the rootCmd.
func Execute() {
	_, err := BuildRootCmd()
	if err != nil {
		log.Error().Msg(err.Error())
		os.Exit(1)
	}

	// normal cli handling
	if err := rootCmd.Execute(); err != nil {
		if cErr, ok := err.(*cli_errors.CommandError); ok {
			if cErr.HasError() {
				log.Error().Msg(err.Error())
			}
			os.Exit(cErr.ExitCode())
		}

		log.Error().Msg(err.Error())
		os.Exit(1)
	}
}

func init() {
	// NOTE: we need to call this super early, otherwise the CLI color output on Windows is broken for the first lines
	// since the log instance is already initialized, replace default zerolog color output with our own
	// use color logger by default
	logger.CliCompactLogger(logger.LogOutputWriter)
	zerolog.SetGlobalLevel(zerolog.InfoLevel)

	config.DefaultConfigFile = "mondoo.yml"

	rootCmd.PersistentFlags().BoolP("verbose", "v", false, "Enable verbose output")
	rootCmd.PersistentFlags().String("log-level", "info", "Set the log level: error, warn, info, debug, trace")
	rootCmd.PersistentFlags().String("api-proxy", "", "Set the proxy for communications with Mondoo Platform API")
	rootCmd.PersistentFlags().Bool("auto-update", true, "Enable automatic provider installation and update")
	// Set NoOptDefVal to allow space-separated bool values (--auto-update false)
	// Without this, "false" would be treated as a positional argument instead of the flag value
	rootCmd.PersistentFlags().Lookup("auto-update").NoOptDefVal = "true"
	_ = viper.BindPFlag("verbose", rootCmd.PersistentFlags().Lookup("verbose"))
	_ = viper.BindPFlag("log-level", rootCmd.PersistentFlags().Lookup("log-level"))
	_ = viper.BindPFlag("api_proxy", rootCmd.PersistentFlags().Lookup("api-proxy"))
	_ = viper.BindPFlag("auto-update", rootCmd.PersistentFlags().Lookup("auto-update"))
	_ = viper.BindEnv("features")
	_ = viper.BindEnv("providers_url")

	config.Init(rootCmd)

	// Register system info provider so that upstream HTTP requests include the
	// Mondoo-PlatformID header. Without this, the server cannot correlate scan
	// requests with managed agents, causing stale check-in times.
	var (
		sysInfoOnce   sync.Once
		cachedSysInfo *rangerUtils.ClientSysInfo
	)
	upstream.SysInfoProvider = func() *rangerUtils.ClientSysInfo {
		sysInfoOnce.Do(func() {
			si, err := sysinfo.Get()
			if err != nil {
				log.Warn().Err(err).Msg("could not determine system information for upstream headers")
				return
			}
			product := rangerUtils.Product{
				Name:    "cnspec",
				Version: cnspec.Version,
				Build:   cnspec.Build,
			}
			csi := &rangerUtils.ClientSysInfo{
				IP:         si.IP,
				Hostname:   si.Hostname,
				PlatformID: si.PlatformId,
				Product:    product,
			}
			if si.Platform != nil {
				csi.PlatformName = si.Platform.Name
				csi.PlatformVersion = si.Platform.Version
				csi.PlatformArch = si.Platform.Arch
			}
			cachedSysInfo = csi
		})
		return cachedSysInfo
	}
}

func initLogger(cmd *cobra.Command) {
	// environment variables always over-write custom flags
	envLevel, ok := logger.GetEnvLogLevel()
	if ok {
		logger.Set(envLevel)
		return
	}

	// retrieve log-level from flags
	level := viper.GetString("log-level")
	if v := viper.GetBool("verbose"); v {
		level = "debug"
	}
	logger.Set(level)
}

var reMdName = regexp.MustCompile(`/([^/]+)\.md$`)

func GenerateMarkdown(dir string) error {
	rootCmd.DisableAutoGenTag = true

	// We need to remove our fancy logo from the markdown output,
	// since it messes with the formatting.
	rootCmd.Long = rootCmdDesc

	files := []string{}
	err := doc.GenMarkdownTreeCustom(rootCmd, dir, func(s string) string {
		files = append(files, s)

		titles := reMdName.FindStringSubmatch(s)
		if len(titles) == 0 {
			return ""
		}
		title := strings.ReplaceAll(titles[1], "_", " ")

		return "---\n" +
			"id: " + titles[1] + "\n" +
			"title: " + title + "\n" +
			"---\n\n"
	}, func(s string) string { return s })
	if err != nil {
		return err
	}

	// we need to remove the first headline, since it is doubled with the
	// headline from the ID. Really annoying, all this needs a rewrite.
	for i := range files {
		file := files[i]
		raw, err := os.ReadFile(file)
		if err != nil {
			return err
		}

		if !strings.HasPrefix(string(raw), "---\nid:") {
			continue
		}

		start := strings.Index(string(raw), "\n## ")
		if start < 0 {
			continue
		}

		end := start
		for i := start + 3; i < len(raw); i++ {
			if raw[i] == '\n' {
				end = i
				break
			}
		}

