180	func (s *LocalScanner) Run(ctx context.Context, job *Job) (*ScanResult, error) {
181		if job == nil {
182			return nil, status.Errorf(codes.InvalidArgument, "missing scan job")
183		}
184	
185		if job.Inventory == nil {
186			return nil, status.Errorf(codes.InvalidArgument, "missing inventory")
187		}
188	
189		if ctx == nil {
190			return nil, errors.New("no context provided to run job with local scanner")
191		}
192	
193		upstream, err := s.getUpstreamConfig(false, job)
194		if err != nil {
195			return nil, err
196		}
197	
198		// The job report type has precedence over the global report type. The default is FULL
199		if job.ReportType == ReportType_FULL {
200			job.ReportType = s.reportType
201		}
202	
203		reports, err := s.distributeJob(job, ctx, upstream)
204		if err != nil {
205			return nil, err
206		}
207	
208		return reports, nil
209	}
