242	// preprocessPolicyFilters expends short registry mrns into full mrns
243	func preprocessPolicyFilters(filters []string) []string {
244		res := make([]string, len(filters))
245		for i := range filters {
246			f := filters[i]
247			if strings.HasPrefix(f, "//") {
248				res[i] = f
249				continue
250			}
251	
252			// expand short registry mrns
253			m := strings.Split(f, "/")
254			if len(m) == 2 {
255				res[i] = policy.NewPolicyMrn(m[0], m[1])
256			} else {
257				res[i] = f
258			}
259		}
260		return res
261	}
262	
263	func createReporter(ctx context.Context, job *Job, upstream *upstream.UpstreamConfig) (Reporter, error) {
264		var reporter Reporter
265		switch job.ReportType {
266		case ReportType_FULL:
267			reporter = NewAggregateReporter()
268	
269			// case where users pass in a bundle directly via a file
270			if job.Bundle != nil {
271				reporter.AddBundle(job.Bundle)
272				return reporter, nil
273			}
274	
275			// - pass in bundle via file
276			// - use Mondoo Platform upstream with/without incognito
277			// - bundles fetched from public registry (not covered here, but in ensureBundle)
278			//
279			// if we use upstream with/without incognito, we want to fetch the bundle here to ensure we only fetch it once
280			// for all assets in the same space
281			if upstream != nil && upstream.Creds != nil {
282				client, err := upstream.InitClient(ctx)
283				if err != nil {
284					return nil, err
285				}
286	
287				services, err := policy.NewRemoteServices(client.ApiEndpoint, client.Plugins, client.HttpClient)
288				if err != nil {
289					return nil, err
290				}
291	
292				// retrieve the bundle for the parent (which is the space). That bundle contains all policies, queries and checks
293				bundle, err := services.GetBundle(ctx, &policy.Mrn{Mrn: upstream.Creds.ParentMrn}) //nolint:staticcheck // SA1019: ParentMrn is deprecated but still used for backward compatibility
294				if err != nil {
295					return nil, err
296				}
297				for i := range bundle.Policies {
298					if bundle.Policies[i].Version == "n/a" {
299						bundle.Policies[i].Version = "0.0.0" // space policy has no version but we need it to compile it
300					}
301				}
302				job.Bundle = bundle // also update the job with the fetched bundle
303				reporter.AddBundle(bundle)
304			}
305		case ReportType_ERROR:
306			reporter = NewErrorReporter()
307		case ReportType_NONE:
308			reporter = NewNoOpReporter()
309		default:
310			return nil, errors.Errorf("unknown report type: %s", job.ReportType)
311		}
312		return reporter, nil
313	}
314	
315	func (s *LocalScanner) distributeJob(job *Job, ctx context.Context, upstream *upstream.UpstreamConfig) (*ScanResult, error) {
316		reporter, err := createReporter(ctx, job, upstream)
317		if err != nil {
318			return nil, err
319		}
320	
321		// Ensure all required providers are installed before we try to run the scan.
322		// We only check here for bundles fetched from the server. Local policy bundles
323		// already have their requirements ensured before compilation in loadPolicies().
324		if job.Bundle != nil && upstream != nil && upstream.Creds != nil && job.Bundle.HasRequirements() {
325			if err := job.Bundle.EnsureRequirements(s.autoUpdate); err != nil {
326				return nil, errors.Wrap(err, "failed to ensure policy requirements")
327			}
328		}
329	
330		log.Info().Msgf("discover related assets for %d asset(s)", len(job.Inventory.Spec.Assets))
331		discoveredAssets, err := discovery.DiscoverAssets(ctx, job.Inventory, upstream, s.recording)
332		if err != nil {
333			return nil, err
334		}
335	
336		// if we had asset errors we want to place them into the reporter
337		for i := range discoveredAssets.Errors {
338			reporter.AddScanError(discoveredAssets.Errors[i].Asset, discoveredAssets.Errors[i].Err)
339		}
340	
341		// For each discovered asset, we initialize a new runtime and connect to it.
342		// Within this process, we set up a catch-all deferred function, that shuts
343		// down all runtimes, in case we exit early.
344		defer func() {
345			for _, asset := range discoveredAssets.Assets {
346				// we can call close multiple times and it will only execute once
347				if asset.Runtime != nil {
348					asset.Runtime.Close()
349				}
350			}
351		}()
352	
353		if len(discoveredAssets.Assets) == 0 {
354			return reporter.Reports(), nil
355		}
356	
357		multiprogress, err := createProgressBar(s.disableProgressBar)
358		if err != nil {
359			return nil, err
360		}

