 92	// BundleExecutionChecksum creates a combined execution checksum from a policy
 93	// and framework. Either may be nil.
 94	func BundleExecutionChecksum(ctx context.Context, policy *Policy, framework *Framework) string {
 95		res := checksums.New
 96		if policy != nil {
 97			res = res.Add(policy.GraphExecutionChecksum)
 98		}
 99		if framework != nil {
100			res = res.Add(framework.GraphExecutionChecksum)
101		}
102		// So far the checksum only includes the policy and the framework
103		// It does not change if any of the jobs changes, only if the policy or the framework changes
104		// To update the resolved policy, when we change how it is generated, change the incorporated version of the resolver
105		res = res.Add(RESOLVER_VERSION)
106	
107		return res.String()
108	}
