188	func (b *Bundle) ConvertEvidence() {
189		for _, f := range b.Frameworks {
190			pol, fm := f.GenerateEvidenceObjects()
191			if pol != nil {
192				b.Policies = append(b.Policies, pol)
193			}
194			if fm != nil {
195				b.FrameworkMaps = append(b.FrameworkMaps, fm)
196			}
197		}
198	}
