 36	// Lint loads a file and lints its content
 37	func Lint(schema resources.ResourcesSchema, opts LintOptions, files ...string) (*Results, error) {
 38		aggregatedResults := &Results{
 39			BundleLocations: []string{},
 40			Entries:         []*Entry{},
 41		}
 42	
 43		// First pass: Parse all files and collect initial metadata for context
 44		for _, file := range files {
 45			absPath, err := filepath.Abs(file)
 46			if err != nil {
 47				return nil, fmt.Errorf("failed to get absolute path for %s: %w", file, err)
 48			}
 49			aggregatedResults.BundleLocations = append(aggregatedResults.BundleLocations, absPath)
 50	
 51			data, err := os.ReadFile(absPath)
 52			if err != nil {
 53				return nil, fmt.Errorf("failed to read file %s: %w", absPath, err)
 54			}
 55	
 56			aggregatedResults.Entries = append(aggregatedResults.Entries, LintPolicyBundle(schema, absPath, data, opts)...)
 57		}
 58	
 59		return aggregatedResults, nil
 60	}
 61	
 62	// LintPolicyBundle lints a yaml formatted bundle
 63	func LintPolicyBundle(schema resources.ResourcesSchema, filename string, data []byte, opts LintOptions) []*Entry {
 64		aggregatedEntries := []*Entry{}
 65	
 66		policyBundle, err := ParseYaml(data)
 67		if err != nil {
 68			// if it is not parsable, we log it
 69			aggregatedEntries = append(aggregatedEntries, &Entry{
 70				RuleID:  BundleInvalidRuleID,
 71				Message: fmt.Sprintf("Cannot parse YAML file %s: %s", filepath.Base(filename), err.Error()),
 72				Level:   LevelError,
 73				Location: []Location{{
 74					File:   filename,
 75					Line:   1,
 76					Column: 1,
 77				}},
 78			})
 79			return aggregatedEntries
 80		}
 81	
 82		policyBundleForCompilation, err := policy.BundleFromYAML(data)
 83		if err != nil {
 84			var locs []Location
 85			locs = append(locs, Location{File: filename, Line: 1, Column: 1})
 86			aggregatedEntries = append(aggregatedEntries, &Entry{
 87				RuleID:   BundleInvalidRuleID,
 88				Message:  "Could not load policy bundle for compilation: " + err.Error(),
 89				Level:    LevelError,
 90				Location: locs,
 91			})
 92		}
 93	
 94		// We have to check for required dependencies before we do anything else
 95		if policyBundleForCompilation != nil {
 96			err := policyBundleForCompilation.EnsureRequirements(opts.SkipProviderDownload)
 97			if err != nil {
 98				aggregatedEntries = append(aggregatedEntries, &Entry{
 99					RuleID:  BundleUnknownFieldRuleID,
100					Message: fmt.Sprintf("Bundle file %s requirements not met: %s", filepath.Base(filename), err.Error()),
101					Level:   LevelError,
102					Location: []Location{{
103						File:   filename,
104						Line:   1,
105						Column: 1,
106					}},
107				})
108			}
109		}
110	
111		// Check for unknown fields (UnmarshalStrict)
112		strictCheckBundle := &policy.Bundle{}
113		if err := k8sYaml.UnmarshalStrict(data, strictCheckBundle); err != nil {
114			aggregatedEntries = append(aggregatedEntries, &Entry{
115				RuleID:  BundleUnknownFieldRuleID,
116				Message: fmt.Sprintf("Bundle file %s contains unknown fields: %s", filepath.Base(filename), err.Error()),
117				Level:   LevelWarning,
118				Location: []Location{{
119					File:   filename,
120					Line:   1,
121					Column: 1,
122				}},
123			})
124		}
125	
126		// check if the file is compilable
127		if policyBundleForCompilation != nil {
128			ctx := context.Background()
129			features := mql.DefaultFeatures
130			features = append(features, byte(mql.FailIfNoEntryPoints))
131			cfg := policy.BundleCompileConf{
132				CompilerConfig: mqlc.NewConfig(schema, features),
133			}
134			_, compileErr := policyBundleForCompilation.CompileExt(ctx, cfg)
135			if compileErr != nil {
136				var locs []Location
137				locs = append(locs, Location{
138					File:   filename,
139					Line:   1,
140					Column: 1,
141				})
142				aggregatedEntries = append(aggregatedEntries, &Entry{
143					RuleID:   BundleCompileErrorRuleID,
144					Message:  "Could not compile policy bundle: " + compileErr.Error(),
145					Level:    LevelError,
146					Location: locs,
147				})
148			}
149		}
150	
151		aggregatedEntries = append(aggregatedEntries, lintParsedBundle(schema, filename, policyBundle)...)
152	
153		return aggregatedEntries
154	}
