156	// lintParsedBundle lints parsed bundle with the default set of rules
157	func lintParsedBundle(schema resources.ResourcesSchema, filename string, policyBundle *Bundle) []*Entry {
158		aggregatedEntries := []*Entry{}
159	
160		bundleRules := GetBundleLintRules()
161		policyRules := GetPolicyLintRules()
162		querypackRules := GetQueryPackLintRules()
163		queryRules := GetQueryLintRules()
164		migrationRules := GetBundleMigrationsLintRules()
165	
166		// Initialize LintContext with data from ALL parsed bundles for cross-file context
167		// This context will be shared for checks that need to know about the whole bundle.
168		// However, some checks are file-specific (like UID uniqueness within a file).
169		// For simplicity, we'll build a context per file, but some parts of the context
170		// (like GlobalQueriesByUid) could be built from all files if needed for more complex checks.
171		// The original code's `globalQueriesUids` was effectively bundle-wide for uniqueness.
172	
173		// For now, let's process file by file, building context as we go.
174		// More complex global context can be added if specific checks require it.
175		// The current structure of checks (e.g. UID uniqueness) is per-file.
176	
177		lintCtx := &LintContext{
178			FilePath:              filename,
179			PolicyBundle:          policyBundle,
180			GlobalQueriesUids:     make(map[string]int),
181			GlobalQueriesByUid:    make(map[string]*Mquery),
182			PolicyUidsInFile:      make(map[string]struct{}),
183			GlobalQueryUidsInFile: make(map[string]struct{}),
184			AssignedQueryUIDs:     make(map[string]struct{}),
185			QueryUsageAsCheck:     make(map[string]struct{}),
186			QueryUsageAsData:      make(map[string]struct{}),
187			VariantMapping:        make(map[string]string),
188		}
189	
190		// Populate context: global queries and variants from the current file
191		for _, q := range policyBundle.Queries {
192			lintCtx.GlobalQueriesUids[q.Uid]++
193			lintCtx.GlobalQueriesByUid[q.Uid] = q
194			for _, variantRef := range q.Variants {
195				lintCtx.VariantMapping[variantRef.Uid] = q.Uid
196			}
197		}
198		// Populate context: variants defined in embedded queries within policies
199		for _, p := range policyBundle.Policies {
200			for _, pg := range p.Groups {
201				for _, checkQuery := range pg.Checks {
202					for _, variantRef := range checkQuery.Variants {
203						lintCtx.VariantMapping[variantRef.Uid] = checkQuery.Uid
204					}
205				}
206				for _, dataQuery := range pg.Queries {
207					for _, variantRef := range dataQuery.Variants {
208						lintCtx.VariantMapping[variantRef.Uid] = dataQuery.Uid
209					}
210				}
211			}
212		}
213	
214		// Populate context: AssignedQueryUIDs, QueryUsageAsCheck, QueryUsageAsData
215		// This needs to iterate through policies.
216		for _, p := range policyBundle.Policies {
217			for _, group := range p.Groups {
218				for _, checkRef := range group.Checks {
219					lintCtx.AssignedQueryUIDs[checkRef.Uid] = struct{}{}
220					lintCtx.QueryUsageAsCheck[checkRef.Uid] = struct{}{}
221					for _, v := range checkRef.Variants { // Also mark variants as assigned
222						lintCtx.AssignedQueryUIDs[v.Uid] = struct{}{}
223						// Variants inherit usage type from parent
224						lintCtx.QueryUsageAsCheck[v.Uid] = struct{}{}
225					}
226				}
227				for _, queryRef := range group.Queries {
228					lintCtx.AssignedQueryUIDs[queryRef.Uid] = struct{}{}
229					lintCtx.QueryUsageAsData[queryRef.Uid] = struct{}{}
230					for _, v := range queryRef.Variants {
231						lintCtx.AssignedQueryUIDs[v.Uid] = struct{}{}
232						lintCtx.QueryUsageAsData[v.Uid] = struct{}{}
233					}
234				}
235			}
236		}
