 37	func NewOutputHandler(config HandlerConfig) (OutputHandler, error) {
 38		conf, err := ParseConfig(config.Format)
 39		if err != nil {
 40			return nil, err
 41		}
 42	
 43		typ := determineOutputType(config.OutputTarget)
 44		switch typ {
 45		case LOCAL_FILE:
 46			return &localFileHandler{file: config.OutputTarget, conf: conf}, nil
 47		case AWS_SQS:
 48			return &awsSqsHandler{sqsQueueUrl: config.OutputTarget, format: conf.format}, nil
 49		case AZURE_SBUS:
 50			return &azureSbusHandler{url: config.OutputTarget, format: conf.format}, nil
 51		case CLI:
 52			fallthrough
 53		default:
 54			res := NewReporter(conf, config.Incognito)
 55			res.RiskThreshold = config.RiskThreshold
 56			return res, nil
 57		}
 58	}
