 60	// determines the output type based on the provided string. we assume type can be inferred without needing
 61	// extra param to specify the type explicitly
 62	func determineOutputType(target string) OutputTarget {
 63		// we fall back to CLI reporting, default behavior
 64		if target == "" {
 65			return CLI
 66		}
 67		if sqsRegex.MatchString(target) {
 68			return AWS_SQS
 69		}
 70		if sbusRegex.MatchString(target) {
 71			return AZURE_SBUS
 72		}
 73	
 74		return LOCAL_FILE
 75	}
