466	func dedupe[T string | int](sliceList []T) []T {
467		allKeys := make(map[T]bool)
468		list := []T{}
469		for _, item := range sliceList {
470			if _, value := allKeys[item]; !value {
471				allKeys[item] = true
472				list = append(list, item)
473			}
474		}
475		return list
476	}

