 22	// GenerateBom generates a BOM from a cnspec json report collection
 23	func GenerateBom(r *cr.Report) []*sbom.Sbom {
 24		if r == nil {
 25			return nil
 26		}
 27	
 28		generator := &sbom.Generator{
 29			Vendor:  "Mondoo, Inc.",
 30			Name:    "cnspec",
 31			Version: cnspec.Version,
 32			Url:     "https://mondoo.com",
 33		}
 34		now := time.Now().UTC().Format(time.RFC3339)
 35	
 36		boms := []*sbom.Sbom{}
 37		for mrn := range r.Assets {
 38			asset := r.Assets[mrn]
 39			bom := &sbom.Sbom{
 40				Generator: generator,
 41				Timestamp: now,
 42				Status:    sbom.Status_STATUS_SUCCEEDED,
 43			}
 44	
 45			bom.Asset = &sbom.Asset{
 46				Name:        asset.GetName(),
 47				PlatformIds: nil,
 48				Platform:    &sbom.Platform{},
 49				Labels:      asset.GetLabels(),
 50				ExternalIds: []*sbom.ExternalID{},
 51				TraceId:     asset.GetTraceId(),
 52			}
 53	
 54			bom.Packages = []*sbom.Package{}
 55	
 56			// extract os packages and python packages
 57			dataPoints := r.Data[mrn]
 58			if dataPoints == nil {
 59				bom.Status = sbom.Status_STATUS_FAILED
 60				bom.ErrorMessage = "no data points found"
 61				boms = append(boms, bom)
 62				continue
 63			}
 64			// ensure deterministic order of enumeration
 65			keys := sortx.Keys(dataPoints.Values)
 66			for _, k := range keys {
 67				dataValue := dataPoints.Values[k]
 68				jsondata, err := cr.JsonValue(dataValue.Content)
 69				if err != nil {
 70					bom.Status = sbom.Status_STATUS_FAILED
 71					bom.ErrorMessage = errors.Wrap(err, "failed to parse json data").Error()
 72					continue
 73				}
 74				rb := BomFields{}
 75				err = json.Unmarshal(jsondata, &rb)
 76				if err != nil {
 77					bom.Status = sbom.Status_STATUS_FAILED
 78					bom.ErrorMessage = errors.Wrap(err, "failed to parse bom fields json data").Error()
 79					continue
 80				}
 81				if rb.Asset != nil {
 82					bom.Asset.Name = rb.Asset.Name
 83					bom.Asset.Platform.Name = rb.Asset.Platform
 84					bom.Asset.Platform.Version = rb.Asset.Version
 85					bom.Asset.Platform.Build = rb.Asset.Build
 86					bom.Asset.Platform.Family = rb.Asset.Family
 87					bom.Asset.Platform.Arch = rb.Asset.Arch
 88					bom.Asset.Platform.Cpes = rb.Asset.CPEs
 89					bom.Asset.Platform.Labels = rb.Asset.Labels
 90					bom.Asset.PlatformIds = enrichPlatformIds(rb.Asset.IDs)
 91					bom.Asset.Platform.Title = rb.Asset.PlatformTitle
 92				}
 93	
 94				if bom.Asset == nil {
 95					bom.Asset = &sbom.Asset{}
 96				}
 97				if bom.Asset.Labels == nil {
 98					bom.Asset.Labels = map[string]string{}
 99				}
100	
101				// store version of running kernel
102				for _, kernel := range rb.KernelInstalled {
103					if kernel.Running {
104						bom.Asset.Labels[LABEL_KERNEL_RUNNING] = kernel.Version
105					}
106				}
107	
108				if rb.Packages != nil {
109					for _, pkg := range rb.Packages {
110						bomPkg := &sbom.Package{
111							Name:         pkg.Name,
112							Version:      pkg.Version,
113							Architecture: pkg.Arch,
114							Origin:       pkg.Origin,
115							Purl:         pkg.Purl,
116							Cpes:         pkg.CPEs,
117							Type:         pkg.Format,
118						}
119	
120						for _, filepath := range pkg.FilePaths {
121							bomPkg.EvidenceList = append(bomPkg.EvidenceList, &sbom.Evidence{
122								Type:  sbom.EvidenceType_EVIDENCE_TYPE_FILE,
123								Value: filepath,
124							})
125						}
126	
127						bom.Packages = append(bom.Packages, bomPkg)
128					}
129				}
130	
131				for _, pkg := range rb.PythonPackages {
132					bomPkg := &sbom.Package{
133						Name:    pkg.Name,
134						Version: pkg.Version,
135						Purl:    pkg.Purl,
136						Cpes:    pkg.CPEs,
137						Type:    "pypi",
138					}
139	
140					// deprecated path, all files are now in the FilePaths field
141					// TODO: update once the python resource returns multiple results
142					if pkg.FilePath != "" {
143						bomPkg.EvidenceList = append(bomPkg.EvidenceList, &sbom.Evidence{
144							Type:  sbom.EvidenceType_EVIDENCE_TYPE_FILE,
145							Value: pkg.FilePath,
146						})
147					}
148	
149					for _, filepath := range pkg.FilePaths {
150						bomPkg.EvidenceList = append(bomPkg.EvidenceList, &sbom.Evidence{
151							Type:  sbom.EvidenceType_EVIDENCE_TYPE_FILE,
152							Value: filepath,
153						})
154					}
155	
156					bom.Packages = append(bom.Packages, bomPkg)
157				}
158	
159				for _, pkg := range rb.NpmPackages {
160					bomPkg := &sbom.Package{
161						Name:    pkg.Name,
162						Version: pkg.Version,
163						Purl:    pkg.Purl,
164						Cpes:    pkg.CPEs,
165						Type:    "npm",
166					}
167	
168					for _, filepath := range pkg.FilePaths {
169						bomPkg.EvidenceList = append(bomPkg.EvidenceList, &sbom.Evidence{
170							Type:  sbom.EvidenceType_EVIDENCE_TYPE_FILE,
171							Value: filepath,
172						})
173					}
174	
175					bom.Packages = append(bom.Packages, bomPkg)
176				}
177			}
178			boms = append(boms, bom)
179		}
180		return boms
181	}
