183	// enrichPlatformIds adds the platform id based on cnquery ids
184	// - AWS EC2 instance ARN
185	func enrichPlatformIds(ids []string) []string {
186		platformIds := []string{}
187		for i := range ids {
188			platformIds = append(platformIds, ids[i])
189	
190			// handle AWS EC2 instance platform identifier and generate AWS ARN as additional identifier
191			// EC2 arns have the following format arn:aws:ec2:<REGION>:<ACCOUNT_ID>:instance/<instance-id>
192			// //platformid.api.mondoo.app/runtime/aws/ec2/v1/accounts/12345678910/regions/us-east-1/instances/i-1234567890abcdef0
193			if strings.HasPrefix(ids[i], "//platformid.api.mondoo.app/runtime/aws/ec2/v1") {
194				ec2mrn, err := mrn.NewMRN(ids[i])
195				if err != nil {
196					continue
197				}
198	
199				accountID, _ := ec2mrn.ResourceID("accounts")
200				region, _ := ec2mrn.ResourceID("regions")
201				instanceID, _ := ec2mrn.ResourceID("instances")
202	
203				if accountID != "" && region != "" && instanceID != "" {
204					platformIds = append(platformIds, fmt.Sprintf("arn:aws:ec2:%s:%s:instance/%s", region, accountID, instanceID))
205				}
206			}
207		}
208		return platformIds
209	}

