17	type fetcher struct {
18		cache map[string]*policy.Bundle
19	}
20	
21	func newFetcher() *fetcher {
22		return &fetcher{
23			cache: map[string]*policy.Bundle{},
24		}
25	}
26	
27	func (f *fetcher) fetchBundles(ctx context.Context, conf mqlc.CompilerConfig, urls ...string) (*policy.Bundle, error) {
28		res := &policy.Bundle{}
29	
30		for i := range urls {
31			url := urls[i]
32			if cur, ok := f.cache[url]; ok {
33				if err := res.AddBundle(cur); err != nil {
34					return nil, errors.Wrap(err, "failed to add cached bundle")
35				}
36				continue
37			}
38	
39			cur, err := f.fetchBundle(url)
40			if err != nil {
41				return nil, err
42			}
43			cur.ConvertQuerypacks()
44	
45			// need to generate MRNs for everything
46			if _, err := cur.CompileExt(ctx, policy.BundleCompileConf{
47				CompilerConfig: conf,
48				RemoveFailing:  true,
49			}); err != nil {
50				return nil, errors.Wrap(err, "failed to compile fetched bundle")
51			}
52	
53			if err = res.AddBundle(cur); err != nil {
54				return nil, errors.Wrap(err, "failed to add fetched bundle")
55			}
56		}
57	
58		return res, nil
59	}
60	
61	func (f *fetcher) fetchBundle(url string) (*policy.Bundle, error) {
62		client := http.Client{
63			CheckRedirect: func(r *http.Request, via []*http.Request) error {
64				r.URL.Opaque = r.URL.Path
65				return nil
66			},
67		}
68	
69		req, err := http.NewRequest("GET", url, nil)
70		if err != nil {
71			return nil, errors.Wrap(err, "failed to set up request to fetch bundle")
72		}
73	
74		req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; cnspec/"+cnspec.Version+"; +http://www.mondoo.com)")
75	
76		resp, err := client.Do(req)
77		if err != nil {
78			return nil, err
79		}
80		defer resp.Body.Close()
81	
82		if resp.StatusCode != 200 {
83			return nil, errors.New("failed to fetch policy bundle from " + url + ": " + resp.Status)
84		}
85	
86		raw, err := io.ReadAll(resp.Body)
87		if err != nil {
88			return nil, err
89		}
90	
91		return policy.BundleFromYAML(raw)
92	}

