 26		filename: "disk-queue",
 27		maxSize:  50000,
 28		sync:     false,
 29	}
 30	
 31	// queueMsg is the being stored in disk queue
 32	type queueMsg struct {
 33		Ts      time.Time
 34		Payload queuePayload
 35	}
 36	
 37	// queuePayload hold the data for the job
 38	type queuePayload struct {
 39		ScanJob []byte // proto encoded scan job
 40	}
 41	
 42	type diskQueueClient struct {
 43		queue   *pdque.Queue
 44		once    sync.Once
 45		wg      sync.WaitGroup
 46		entries chan Job
 47		handler func(job *Job)
 48	}
 49	
 50	func diskQueueEntryBuilder() any {
 51		return &queueMsg{}
 52	}
 53	
 54	// newDqueClient creates a new dque client which stores scan job events on disk
 55	// It is a First In First Out (FIFO) queue
 56	//
 57	// To push a scan job onto the queue, just place a new *ScanJob onto go channel
 58	// dqueClient.Channel() <- *job
 59	func newDqueClient(config diskQueueConfig, handler func(job *Job)) (*diskQueueClient, error) {
 60		var err error
 61	
 62		q := &diskQueueClient{
 63			handler: handler,
 64		}
 65	
 66		err = os.MkdirAll(config.dir, 0o700)
 67		if err != nil {
 68			return nil, fmt.Errorf("cannot create queue directory: %s", err)
 69		}
 70	
 71		q.queue, err = pdque.NewOrOpen(config.filename, config.dir, config.maxSize, diskQueueEntryBuilder)
 72		if err != nil {
 73			return nil, err
 74		}
 75	
 76		q.entries = make(chan Job)
 77	
 78		q.wg.Add(2)
 79		go q.pusher()
 80		go q.popper()
 81		return q, nil
 82	}
 83	
 84	// Stop closes the client
 85	func (c *diskQueueClient) Stop() {
 86		c.once.Do(func() {
 87			close(c.entries)
 88			c.queue.Close()
 89			c.wg.Wait()
 90		})
 91	}
 92	
 93	func (c *diskQueueClient) Channel() chan<- Job {
 94		return c.entries
 95	}
 96	
 97	// pusher iterates over all new ScanJob events and places them into the disk queue
 98	func (c *diskQueueClient) pusher() {
 99		defer c.wg.Done()
100		for sj := range c.entries {
101	
102			// we marshal the scan job since dque uses gob marshaling which would fail otherwise
103			data, err := proto.Marshal(&sj)
104			if err != nil {
105				log.Warn().Err(err).Msg("cannot marshal scan job")
106				continue
107			}
108	
109			err = c.queue.Enqueue(&queueMsg{time.Now(), queuePayload{
110				ScanJob: data,
111			}})
112			if err != nil {
113				log.Warn().Err(err).Msg("cannot push scan job on disk queue")
114			}
115		}
116	}
117	
118	// popper reads from the disk queue and runs the handle function per event
119	func (c *diskQueueClient) popper() {
120		defer c.wg.Done()
121		for {
122			// pop next item from queue
123			entry, err := c.queue.DequeueBlock()
124			if err != nil {
125				switch err {
126				case pdque.ErrQueueClosed:
127					return
128				default:
129					log.Error().Err(err).Msg("could not pop job from disk queue")
130					continue
131				}
132			}
133	
134			// convert the event into our own event
135			record, ok := entry.(*queueMsg)
136			if !ok {
137				log.Error().Msg("invalid type stored in queue")
138				continue
139			}
140	
141			// unmarshal the protobuf content into scan job and run handler
142			var scanJob Job
143			err = proto.Unmarshal(record.Payload.ScanJob, &scanJob)
144			if err != nil {
145				log.Error().Err(err).Msg("could not unmarshal the scan job")
146				continue
147			}
148			c.handler(&scanJob)
149		}
150	}

