46	// Validate that this collector job is wired correctly and adheres to internal consistency
47	func (c *CollectorJob) Validate() error {
48		invalid := false
49		invalidCollectorJobError := newInvalidCollectorJobError()
50	
51		for _, job := range c.ReportingJobs {
52			for ref := range job.ChildJobs {
53				if _, ok := c.ReportingJobs[ref]; !ok {
54					invalid = true
55					invalidCollectorJobError.addInvalidSpec(job.Uuid, ref)
56				}
57			}
58	
59			for ref := range job.Notify {
60				ref := job.Notify[ref]
61				if _, ok := c.ReportingJobs[ref]; !ok {
62					invalid = true
63					invalidCollectorJobError.addInvalidNotifier(job.Uuid, ref)
64				}
65			}
66		}
67	
68		if !invalid {
69			return nil
70		}
71	
72		return invalidCollectorJobError
73	}

